'use strict';
window.JournalClub=(()=>{
 const KEY='pepper-improvement-journal-club:v1',fields=['goal','strategy_results','pepper_basis','engineering_outcome','tradeoffs_metrics','next_step'];
 const traits={disease:['抗病','Disease resistance'],stress:['非生物胁迫','Abiotic stress'],architecture:['株型','Architecture'],flowering_uniformity:['开花整齐度','Flowering uniformity'],flowering_stability:['花期稳定性','Flowering stability'],flowering_time:['花期调控','Flowering timing'],yield:['产量','Yield'],nutrition:['营养品质','Nutrition'],fruit_quality:['果实性状','Fruit traits']};
 const states={discussion:['待讨论','To discuss'],evidence:['需补证据','Needs evidence'],priority:['优先验证','Priority for validation'],paused:['暂缓','On hold']};
 const labels={goal:['改良目标','Improvement goal'],strategy_results:['原研究：策略与结果','Original strategy and results'],pepper_basis:['辣椒适用性与证据缺口','Pepper applicability and evidence gaps'],engineering_outcome:['拟改造方式与预期结果（待验证）','Proposed engineering and outcome (untested)'],tradeoffs_metrics:['潜在代价与成功指标','Trade-offs and success criteria'],next_step:['下一步最小行动','Smallest next action']};
 const copy={intro:['从文献或基因功能出发提出辣椒性状改良方案。自有多组学候选的纯功能敲除研究不列入此组会。','Develop pepper trait-improvement ideas from literature or gene-function studies. Knockouts solely for functional studies of our own multi-omics candidates are outside this journal club.'],local:['讨论状态、自拟方案和项目备注仅保存在此浏览器，不会同步给其他组员。请导出备份以便迁移；上传备份前确认其中没有不宜共享的研究信息。','Discussion decisions, custom ideas and project notes stay in this browser, without team synchronization. Export backups to transfer them; review research information before sharing.'],draft:['讨论草案 · 先核对原文；辣椒同源性及功能保守性待核验','Discussion draft · Check the original; pepper orthology and functional conservation remain unverified'],all:['全部','All'],transfer:['源物种已有干预结果','Intervention demonstrated in source species'],hypothesis:['基因功能启发的新设想','Gene-function-based hypothesis'],add:['加入项目清单','Add to to-do list'],added:['移出项目清单','Remove from to-do list'],new:['添加自己的方案','Add your own idea'],title:['方案名称','Idea title'],source:['支持文献链接（HTTPS）','Supporting paper URL (HTTPS)'],trait:['改良性状','Improvement trait'],kind:['方案类型','Idea type'],owner:['负责人（可留空）','Owner (optional)'],due:['下次检查日期','Review date'],reason:['讨论结论／优先或暂缓原因','Decision / prioritization or hold rationale'],action:['当前下一步行动','Current next action'],save:['保存方案','Save idea'],edit:['编辑方案','Edit idea'],cancel:['取消编辑','Cancel editing'],saved:['已保存在此浏览器','Saved in this browser'],failed:['浏览器保存失败；本次内容仍在内存中，请立即导出备份。','Browser save failed; current data remains in memory. Export a backup now.'],export:['导出备份 JSON','Export JSON backup'],restore:['导入备份 JSON','Import JSON backup'],csv:['导出当前清单 CSV','Export current list CSV'],invalid:['输入不完整或备份格式不正确，未导入。','Incomplete input or invalid backup; nothing imported.'],empty:['当前没有符合条件的方案。可先从 Journal Club 加入项目，或添加自己的方案。','No matching ideas. Add one from Journal Club or create your own.'],scope:['该方案以辣椒性状改良为目标，不是仅用于验证自有多组学候选基因功能。','This idea targets pepper trait improvement, rather than only functional testing of our own multi-omics candidates.'],sourceRead:['打开支持文献','Open supporting paper'],long:['原有完整文献解读','Full archived commentary'],untitled:['自拟方案','Custom idea'],formNote:['请简述事实与预测，避免把未核验的同源性写成已证实。自填文字按原语言保存。','Separate findings from predictions; do not present unchecked orthology as established. Your text is saved in its original language.']};
 let records={},persistent=true,traitFilter='',stateFilter='',kindFilter='',search='';
 const idOK=id=>/^(paper-[a-f0-9]{16}|idea-[a-z0-9-]{8,80})$/.test(id),urlOK=s=>{try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}};
 function valid(r){if(!r||typeof r!=='object'||!states[r.state]||typeof r.tracked!=='boolean'||!Number.isFinite(Date.parse(r.updated_at)))return false;for(const k of ['owner','due','reason','action'])if(typeof r[k]!=='string'||r[k].length>10000)return false;if(r.custom){const c=r.custom;if(typeof c.url!=='string'||!urlOK(c.url)||typeof c.title!=='string'||!c.title.trim()||c.title.length>10000||!['transfer','hypothesis'].includes(c.kind)||!traits[c.trait]||!['zh','en'].includes(c.language)||fields.some(k=>typeof c[k]!=='string'||!c[k].trim()||c[k].length>10000))return false;}return true;}
 try{const value=JSON.parse(localStorage.getItem(KEY)||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))records=Object.fromEntries(Object.entries(value).filter(([id,r])=>idOK(id)&&valid(r)));}catch{persistent=false;}
 function get(id){return records[id]||{tracked:false,state:'discussion',owner:'',due:'',reason:'',action:'',updated_at:new Date().toISOString()};}
 function set(id,patch){const next={...get(id),...patch,updated_at:new Date().toISOString()};if(!idOK(id)||!valid(next))throw Error('Invalid record');records[id]=next;try{localStorage.setItem(KEY,JSON.stringify(records));persistent=true;}catch{persistent=false;}return persistent;}
 function backup(){return {format:'pepper-improvement-journal-club',version:1,records};}
 function restore(value){if(value?.format!=='pepper-improvement-journal-club'||value.version!==1||!value.records||typeof value.records!=='object'||Array.isArray(value.records))throw Error('Invalid backup');const entries=Object.entries(value.records);if(entries.length>5000||entries.some(([id,r])=>!idOK(id)||!valid(r)))throw Error('Invalid records');const merged={...records};for(const[id,r]of entries)if(!merged[id]||Date.parse(r.updated_at)>Date.parse(merged[id].updated_at))merged[id]=r;records=merged;try{localStorage.setItem(KEY,JSON.stringify(records));persistent=true;}catch{persistent=false;}return persistent;}
 function ideas(papers,lang){return [...papers.filter(p=>p.journal_club?.origin==='literature').map(p=>({id:p.id,title:p.title,url:p.url,paper:true,traits:p.journal_club.traits,kind:p.journal_club.kind,...p.journal_club[lang]})),...Object.entries(records).filter(([,r])=>r.custom).map(([id,r])=>({id,...r.custom,traits:[r.custom.trait]}))];}
 const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function mount(root,{lang,papers,projectOnly,paperHref,download}){
  const i=lang==='en'?1:0,t=k=>(copy[k]||[k,k])[i],word=(dict,k)=>dict[k][i],button=(text,fn)=>{const b=node('button',text);b.type='button';b.onclick=fn;return b;},link=(text,url)=>{const a=node('a',text);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;};
  const rerender=()=>{root.replaceChildren();mount(root,{lang,papers,projectOnly,paperHref,download});};
  root.append(node('p',t('intro'),'summary'),node('p',t('local'),'jc-local'));
  const toolbar=node('div',undefined,'jc-toolbar'),notice=node('p',persistent?'':t('failed'),'jc-notice');notice.setAttribute('aria-live','polite');
  const select=(dict,current,change,label)=>{const s=node('select');s.setAttribute('aria-label',label);const all=node('option',t('all')+' · '+label);all.value='';s.append(all);for(const[k,v]of Object.entries(dict)){const o=node('option',v[i]);o.value=k;s.append(o);}s.value=current;s.onchange=()=>{change(s.value);rerender();};return s;};
  toolbar.append(select(traits,traitFilter,v=>traitFilter=v,t('trait')),select(states,stateFilter,v=>stateFilter=v,lang==='en'?'Decision':'讨论状态'),select({transfer:copy.transfer,hypothesis:copy.hypothesis},kindFilter,v=>kindFilter=v,t('kind')));
  const query=node('input');query.type='search';query.value=search;query.placeholder=lang==='en'?'Search ideas':'搜索改良方案';query.setAttribute('aria-label',query.placeholder);query.onchange=()=>{search=query.value;rerender();};toolbar.append(query);root.append(toolbar);
  const formSlot=node('div');root.append(formSlot);
  function editIdea(existing){formSlot.replaceChildren();const form=node('form',undefined,'jc-form'),inputs={};form.append(node('h3',t(existing?'edit':'new')),node('p',t('formNote')));for(const[k,label]of [['title',t('title')],['url',t('source')],...fields.map(k=>[k,word(labels,k)])]){const wrap=node('label',label),input=node(fields.includes(k)?'textarea':'input');input.required=true;input.maxLength=10000;if(k==='url')input.type='url';input.value=existing?.[k]||'';wrap.append(input);form.append(wrap);inputs[k]=input;}
   for(const[k,dict]of [['trait',traits],['kind',{transfer:copy.transfer,hypothesis:copy.hypothesis}]]){const wrap=node('label',t(k)),s=node('select');for(const[v,l]of Object.entries(dict)){const o=node('option',l[i]);o.value=v;s.append(o);}s.value=existing?.[k]||Object.keys(dict)[0];wrap.append(s);inputs[k]=s;form.append(wrap);}
   const scope=node('label',undefined,'jc-check'),check=node('input');check.type='checkbox';check.required=true;scope.append(check,document.createTextNode(t('scope')));form.append(scope);const submit=node('button',t('save'));submit.type='submit';form.append(submit,button(t('cancel'),()=>formSlot.replaceChildren()));
   form.onsubmit=e=>{e.preventDefault();const c=Object.fromEntries(Object.entries(inputs).map(([k,n])=>[k,n.value.trim()]));if(!check.checked||!urlOK(c.url)||!c.title||fields.some(k=>!c[k])){notice.textContent=t('invalid');return;}c.language=existing?.language||lang;const id=existing?.id||'idea-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);set(id,{custom:c,tracked:true});rerender();};formSlot.append(form);}
  const actions=node('div',undefined,'paper-actions');actions.append(button(t('new'),()=>editIdea()),button(t('export'),()=>download('pepper-improvement-backup.json',JSON.stringify(backup(),null,2),'application/json')));
  const upload=node('input');upload.type='file';upload.accept='.json,application/json';upload.hidden=true;upload.onchange=async()=>{try{const file=upload.files[0];if(!file)return;if(file.size>10000000)throw Error('Too large');restore(JSON.parse(await file.text()));rerender();}catch{notice.textContent=t('invalid');}finally{upload.value='';}};actions.append(button(t('restore'),()=>upload.click()),upload);root.append(actions,notice);
  const rows=ideas(papers,lang).filter(c=>(!projectOnly||get(c.id).tracked)&&(!traitFilter||c.traits.includes(traitFilter))&&(!stateFilter||get(c.id).state===stateFilter)&&(!kindFilter||c.kind===kindFilter)&&(!search||[c.title,...fields.map(k=>c[k])].join(' ').toLowerCase().includes(search.toLowerCase())));
  actions.append(button(t('csv'),()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const headers=['title','url','traits','kind',...fields,'state','owner','due','reason','action'];const lines=[headers,...rows.map(c=>{const r=get(c.id);return [c.title,c.url,c.traits.join('; '),c.kind,...fields.map(k=>c[k]),r.state,r.owner,r.due,r.reason,r.action];})];download('pepper-improvement.csv','\ufeff'+lines.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}));
  root.append(node('p',String(rows.length)+(lang==='en'?' ideas':' 个方案'),'jc-count'));if(!rows.length)root.append(node('p',t('empty'),'empty'));
  for(const c of rows){const card=node('article',undefined,'paper jc-card'),r=get(c.id);card.append(node('h3',c.title));const badges=node('div',undefined,'tags');for(const trait of c.traits)badges.append(node('span',word(traits,trait),'tag'));badges.append(node('span',t(c.kind),'badge'));card.append(badges,node('p',t('draft'),'jc-evidence'));
   const list=node('dl',undefined,'jc-sections');for(const field of fields)list.append(node('dt',word(labels,field)),node('dd',c[field]));card.append(list);
   const source=node('div',undefined,'paper-actions');if(urlOK(c.url))source.append(link(t('sourceRead'),c.url));if(c.paper)source.append(link(t('long'),paperHref(c.id)));else source.append(button(t('edit'),()=>editIdea(c)));source.append(button(t(r.tracked?'added':'add'),()=>{set(c.id,{tracked:!r.tracked});rerender();}));card.append(source);
   if(r.tracked){const controls=node('div',undefined,'jc-project');const state=node('select');state.setAttribute('aria-label',lang==='en'?'Project status':'项目状态');for(const[k,v]of Object.entries(states)){const o=node('option',v[i]);o.value=k;state.append(o);}state.value=r.state;state.onchange=()=>{set(c.id,{state:state.value});rerender();};controls.append(state);
    for(const key of ['owner','due','reason','action']){const wrap=node('label',t(key)),input=node(['reason','action'].includes(key)?'textarea':'input');if(key==='due')input.type='date';input.value=r[key];input.maxLength=10000;input.oninput=()=>{notice.textContent=t(set(c.id,{[key]:input.value})?'saved':'failed');};wrap.append(input);controls.append(wrap);}card.append(controls);}
   root.append(card);
  }
 }
 return {mount,get,set,backup,restore,ideas,valid};
})();
